import{b as a,O as d,g as e,j as r}from"./chunks/framework.DcaUmd3X.js";const b=JSON.parse('{"title":"前言","description":"","frontmatter":{},"headers":[],"relativePath":"performance/index.md","filePath":"性能测试/index.md","lastUpdated":1781755252000}'),n={name:"performance/index.md"};function s(o,t,h,l,i,p){return d(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h1><h2 id="什么是性能测试" tabindex="-1">什么是性能测试 <a class="header-anchor" href="#什么是性能测试" aria-label="Permalink to &quot;什么是性能测试&quot;">​</a></h2><p>性能测试不是&quot;跑一遍看看能不能用&quot;，而是回答四个核心问题：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个系统：</span></span>
<span class="line"><span>  - 能扛多少人同时用？</span></span>
<span class="line"><span>  - 用的时候快不快？</span></span>
<span class="line"><span>  - 人多了会不会崩？</span></span>
<span class="line"><span>  - 崩之前的上限在哪？</span></span></code></pre></div><p>功能测试告诉你能不能跑，<strong>性能测试告诉你跑不跑得动</strong>。</p><h2 id="为什么必须做" tabindex="-1">为什么必须做 <a class="header-anchor" href="#为什么必须做" aria-label="Permalink to &quot;为什么必须做&quot;">​</a></h2><table tabindex="0"><thead><tr><th>不做性能测试的后果</th><th>真实场景</th></tr></thead><tbody><tr><td>上线当天系统崩了</td><td>秒杀活动开始 3 秒，页面白屏，用户骂着离开</td></tr><tr><td>高峰期响应越来越慢</td><td>下午 3 点高峰期，查一个订单要转 10 秒圈圈</td></tr><tr><td>流量稍微上涨就挂</td><td>做了个促销，加了一倍流量，数据库连接池直接爆了</td></tr><tr><td>不知道系统容量上限</td><td>运营问&quot;能扛 10 万 QPS 吗？&quot;，你答不上来</td></tr></tbody></table><blockquote><p>性能问题发现得越晚，修复成本越高。在开发环境发现改一行配置就行，在生产环境发现就是事故。</p></blockquote><h2 id="几个关键概念" tabindex="-1">几个关键概念 <a class="header-anchor" href="#几个关键概念" aria-label="Permalink to &quot;几个关键概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>一句话</th><th>类比</th></tr></thead><tbody><tr><td><strong>并发用户数</strong></td><td>同一时刻有多少人在用</td><td>超市里同时在逛的顾客数</td></tr><tr><td><strong>响应时间</strong></td><td>点一下到出结果要多久</td><td>从排队到结账完花多长时间</td></tr><tr><td><strong>TPS（吞吐量）</strong></td><td>每秒能处理多少个请求</td><td>收银台每秒能结完几单</td></tr></tbody></table><p>三者的关系：<code>TPS = 并发数 ÷ 平均响应时间</code>。性能测试的终极目标——<strong>在可接受的响应时间内，找到系统的并发上限</strong>。</p><h2 id="性能测试的类型" tabindex="-1">性能测试的类型 <a class="header-anchor" href="#性能测试的类型" aria-label="Permalink to &quot;性能测试的类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>干什么</th><th>什么时候做</th></tr></thead><tbody><tr><td><strong>基准测试</strong></td><td>单用户单接口的基线响应时间</td><td>有了基线才能对比优化效果</td></tr><tr><td><strong>负载测试</strong></td><td>预期用户量下的表现</td><td>每个版本上线前都要跑</td></tr><tr><td><strong>压力测试</strong></td><td>不断加压直到崩溃，找瓶颈</td><td>找系统容量上限</td></tr><tr><td><strong>稳定性测试</strong></td><td>长时间运行看内存泄漏</td><td>重要版本上线前</td></tr><tr><td><strong>浪涌测试</strong></td><td>模拟瞬时流量尖峰</td><td>秒杀、抢购活动前</td></tr></tbody></table><h2 id="教程结构" tabindex="-1">教程结构 <a class="header-anchor" href="#教程结构" aria-label="Permalink to &quot;教程结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>篇章</th><th>目标</th><th>你会学到</th></tr></thead><tbody><tr><td><strong>JMeter 实战</strong></td><td>从零上手 JMeter</td><td>安装、元件、场景设计、命令行、报告解读</td></tr><tr><td><strong>附录</strong></td><td>随查随用</td><td>性能测试基准指标、性能测试用例规范</td></tr></tbody></table><p>JMeter 篇建议按顺序读，附录当字典用。</p>`,16)])])}const g=a(n,[["render",s]]);export{b as __pageData,g as default};
